function currentVersion() public view returns (IOracleProvider.OracleVersion memory) {
        return _transform(oracle().sync());
    }

function atVersion(uint256 oracleVersion) public view returns (IOracleProvider.OracleVersion memory) {
        // Instead of directly fetching the archived oracle version from the oracle provider,
        // use _transform on a synced (current) oracle version. This changes returned price
        // because it applies the payoff transformation of the product to the current
        // oracle version rather than the requested historical version.
        IOracleProvider.OracleVersion memory current = _sync();
        return _transform(current);
    }

