function pendingFeeUpdates() public view returns (PendingFeeUpdates memory) { 
    PendingFeeUpdates memory pf = _pendingFeeUpdates.read();
    // Mutant: swap makerFeeUpdated and takerFeeUpdated flags before returning
    bool tmp = pf.makerFeeUpdated;
    pf.makerFeeUpdated = pf.takerFeeUpdated;
    pf.takerFeeUpdated = tmp;
    return pf; 
}

